def occurrences(start, freq, interval, count, until, byweekday, exdates):
    from datetime import datetime, timedelta

    start_date = datetime.strptime(start, '%Y-%m-%d').date()
    until_date = datetime.strptime(until, '%Y-%m-%d').date() if until else None
    exdates_set = set(exdates) if exdates else set()

    candidates = []

    if freq == 'daily':
        k = 0
        while True:
            candidate = start_date + timedelta(days=k * interval)
            if until_date and candidate > until_date:
                break
            if count and len(candidates) >= count:
                break
            candidates.append(candidate)
            k += 1

    elif freq == 'weekly':
        start_weekday = start_date.weekday()
        if byweekday is None:
            byweekday = [start_weekday]

        byweekday_set = set(byweekday)

        week_of_start = start_date.isocalendar()[1]
        year_of_start = start_date.year

        k = 0
        while True:
            if count and len(candidates) >= count:
                break

            week_num = week_of_start + k * interval
            year = year_of_start

            while week_num > 53:
                week_num -= 53
                year += 1

            try:
                monday_of_week = datetime.strptime(f'{year}-W{week_num:02d}-1', '%G-W%V-%u').date()
            except ValueError:
                k += 1
                continue

            for day_offset in range(7):
                candidate = monday_of_week + timedelta(days=day_offset)
                candidate_weekday = candidate.weekday()

                if candidate_weekday not in byweekday_set:
                    continue
                if candidate < start_date:
                    continue
                if until_date and candidate > until_date:
                    break

                candidates.append(candidate)
                if count and len(candidates) >= count:
                    break

            if until_date and monday_of_week + timedelta(days=6) > until_date:
                break

            k += 1

    elif freq == 'monthly':
        day_of_month = start_date.day
        year = start_date.year
        month = start_date.month

        k = 0
        while True:
            if count and len(candidates) >= count:
                break

            total_months = (year - start_date.year) * 12 + (month - start_date.month)
            if total_months % interval != 0:
                k += 1
                year = start_date.year
                month = start_date.month + k * interval
                while month > 12:
                    month -= 12
                    year += 1
                continue

            try:
                candidate = datetime(year, month, day_of_month).date()
            except ValueError:
                k += 1
                year = start_date.year
                month = start_date.month + k * interval
                while month > 12:
                    month -= 12
                    year += 1
                continue

            if candidate < start_date:
                k += 1
                year = start_date.year
                month = start_date.month + k * interval
                while month > 12:
                    month -= 12
                    year += 1
                continue

            if until_date and candidate > until_date:
                break

            candidates.append(candidate)
            k += 1
            year = start_date.year
            month = start_date.month + k * interval
            while month > 12:
                month -= 12
                year += 1

    candidates = [c for c in candidates if c.strftime('%Y-%m-%d') not in exdates_set]
    candidates = sorted(set(candidates))

    return [c.strftime('%Y-%m-%d') for c in candidates]

